from common import *

def room():
    c1 = calc('c1', "Drude copper: lifetime, mean free path, heat conduction", 'normal',
      "Copper at 300 K: $n=8.47\\times10^{28}$ m$^{-3}$, resistivity $\\rho=1.70\\times10^{-8}\\,\\Omega$m. Drude: $m\\dot v+mv/\\tau=-eE$, $\\sigma=ne^2\\tau/m$ (script 4.1). The Fermi velocity is $v_F=\\hbar k_F/m$ with $k_F=(3\\pi^2n)^{1/3}$, the mean free path $\\ell=v_F\\tau$, and the Wiedemann–Franz law is $\\kappa=\\frac{\\pi^2}{3}\\big(\\frac{k_B}{e}\\big)^2T\\sigma$.",
      V('e', 'kB', n=8.47e28, rho=1.70e-8, T=300.0),
      [step('tau', "Relaxation time $\\tau=m/(ne^2\\rho)$ in s.", "me/(n*e**2*rho)", "s", ["s", "fs", "ps", "m"], 0.02,
            "$\\sigma=1/\\rho=ne^2\\tau/m$. The result is $\\sim2.5\\times10^{-14}$ s = 25 fs: electrons scatter about $4\\times10^{13}$ times per second."),
       step('vF', "Fermi velocity $v_F$ in m/s.", "hbar*(3*pi**2*n)**(1/3)/me", "m/s", ["m/s", "km/s", "cm/s", "c"], 0.02,
            "Not the thermal velocity $\\sqrt{3k_BT/m}\\approx10^5$ m/s but $v_F\\approx1.6\\times10^6$ m/s: Pauli exclusion again."),
       step('ell', "Mean free path $\\ell=v_F\\tau$ in nm.", "vF*tau*1e9", "nm", ["nm", "um", "A", "m"], 0.03,
            "About 40 nm, i.e. $\\sim100$ lattice constants. The Drude picture of electrons bumping into ion cores (spacing 0.25 nm) would give $\\sim0.3$ nm: a periodic lattice does not scatter, only deviations from it do (phonons, defects)."),
       step('kappa', "Wiedemann–Franz thermal conductivity $\\kappa=\\frac{\\pi^2}{3}(k_B/e)^2T/\\rho$ in W m$^{-1}$K$^{-1}$.", "pi**2/3*(kB/e)**2*T/rho", "W/(m K)", ["W/(m K)", "W/(m K^2)", "W/K", "J/(m^3 K)"], 0.02,
            "Lorenz number $L=\\frac{\\pi^2}{3}(k_B/e)^2=2.44\\times10^{-8}$ W$\\Omega$K$^{-2}$. Measured Cu: 400 W/mK. (The HS23 key prints $\\pi^2/2$ in its Wiedemann–Franz line, the script has $\\pi^2/3$; only ratios are asked there.)"),
       step('RH', "Hall coefficient $R_H=-1/(ne)$ in m$^3$/C (keep the sign).", "-1/(n*e)", "m^3/C", ["m^3/C", "C m^-3", "m^2/(V s)", "Ohm m"], 0.02,
            "Drude gives a negative $R_H$ for electrons (script 4.9): the sign tells the carrier type. Cu agrees; Al, Zn, Be do not, a failure of the free-electron picture.")],
      70)

    c2 = calc('c2', "Phonons or defects? Resistivity ratios for A and B", 'normal',
      "Zheludev, Jan 2024, Problem 2b. Metals A and B as in the Fermi Sea room: free electrons, same cell volume, $n_B=2n_A$. Rates add (Matthiessen): $\\rho=\\rho_{\\rm ph}+\\rho_{\\rm def}$. Use $\\rho=m/(ne^2\\tau)$ and, from the script, $\\rho_{\\rm def}\\simeq3n_dQ/(e^2v_F\\nu(\\epsilon_F))$ with $v_F\\propto n^{1/3}$ and $\\nu(\\epsilon_F)\\propto n^{1/3}$. At $T\\gg\\Theta_D$ the scattering rate $\\tau^{-1}$ is proportional to the number of phonons, $N_p=9nk_BT/(2\\hbar\\omega_DV_0)$. $\\Theta_{D,A}=100$ K.",
      dict(nA=1.0, nB=2.0, ThetaA=100.0, ThetaB=200.0, rhoRatio=2.0),
      [step('r1', "At 300 K with $\\Theta_{D,A}=\\Theta_{D,B}=100$ K: $\\rho_A/\\rho_B$.", "nB/nA", "dimensionless", ["dimensionless", "K", "Ohm m", "eV"], 0.02,
            "Same $N_p$ so the same $\\tau$; then $\\rho=m/(ne^2\\tau)\\propto1/n$. Metal A (fewer electrons) has the higher resistivity: $\\rho_A/\\rho_B=2$. (Key: $\\rho\\propto1/(k_F^2\\nu\\tau)\\propto n^{-2/3}n^{-1/3}$.)"),
       step('r2', "With $\\Theta_{D,B}=200$ K instead: $\\rho_A/\\rho_B$.", "nB/nA*ThetaB/ThetaA", "dimensionless", ["dimensionless", "K", "Ohm m", "eV"], 0.02,
            "$N_p\\propto1/\\Theta_D$ at high $T$ (stiffer lattice, fewer phonons): $\\tau_A^{-1}/\\tau_B^{-1}=\\Theta_B/\\Theta_A=2$, so $\\rho_A/\\rho_B=2\\times2=4$; A is still higher."),
       step('tauratio', "At 5 K the defect scattering dominates and $\\rho_A=2\\rho_B$. Ratio of relaxation times $\\tau_A/\\tau_B$.", "(nB/nA)/rhoRatio", "dimensionless", ["dimensionless", "K", "Ohm m", "eV"], 0.02,
            "$\\tau=m/(ne^2\\rho)$: $\\tau_A/\\tau_B=\\frac{n_B\\rho_B}{n_A\\rho_A}=2\\times\\frac12=1$."),
       step('ndratio', "Ratio of the defect densities $n_{d,A}/n_{d,B}$ (same cross section $Q$).", "rhoRatio*(nA/nB)**(2/3)", "dimensionless", ["dimensionless", "K", "Ohm m", "eV"], 0.02,
            "$\\rho_{\\rm def}\\propto n_d/(v_F\\nu)\\propto n_d\\,n^{-2/3}$, so $n_{d,A}/n_{d,B}=2\\times2^{-2/3}=2^{1/3}=1.26$. Cross-check with $\\tau\\propto1/(v_Fn_d)$: $2^{1/3}\\times2^{-1/3}=1$, consistent with the previous step."),
       step('kratio', "Thermal conductivity ratio $\\kappa_A/\\kappa_B$ at 5 K (Wiedemann–Franz).", "1/rhoRatio", "dimensionless", ["dimensionless", "K", "Ohm m", "eV"], 0.02,
            "$\\kappa=\\frac{\\pi^2}{3}(k_B/e)^2T\\sigma\\propto1/\\rho$ for elastic scattering: $\\kappa_A/\\kappa_B=\\rho_B/\\rho_A=1/2$.")],
      60)

    c3 = calc('c3', "Hall detective: what carriers, how many, how fast?", 'normal',
      "HS20 task 3 (Hall effect) with numbers. A cubic sample of edge $d=1.0$ mm carries a current $I=10$ mA along $y$ in a field $B_z=0.50$ T. The transverse (Hall) voltage is $U_H=6.2415$ mV, the zero-field resistivity is $\\rho=1.25\\times10^{-2}\\,\\Omega$m and the effective mass is $m^*=0.2m_e$. Steady state of $m\\dot{\\vec v}+m\\vec v/\\tau=-e(\\vec E+\\vec v\\times\\vec B)$ with $j_x=0$ gives $|E_x|=j_yB_z/(ne)$ and $U_H=dE_x$ (the key writes this as $n=-dj_yB_z/(eU_H)$; the sign only encodes the electron charge).",
      V('e', d=1.0e-3, I=1.0e-2, B=0.5, UH=6.2415e-3, rho=1.25e-2, ms=0.2),
      [step('jy', "Current density $j_y=I/d^2$ in A/m$^2$.", "I/d**2", "A/m^2", ["A/m^2", "A/m", "A", "A m"], 0.01,
            "Cross-section $d\\times d$."),
       step('n', "Carrier density $n=d\\,j_yB_z/(e\\,|U_H|)$ in m$^{-3}$.", "d*jy*B/(e*UH)", "m^-3", ["m^-3", "m^-2", "cm^-3", "m^3"], 0.02,
            "From the $x$ component of the steady-state Drude equation. Equivalent to $U_H=IB/(ned)$: a thinner sample gives a larger signal."),
       step('RH', "Hall coefficient $R_H=-1/(ne)$ in m$^3$/C. The sign shows which carriers dominate.", "-1/(n*e)", "m^3/C", ["m^3/C", "C m^-3", "m^2/(V s)", "Ohm m"], 0.02,
            "Negative means electrons. With $\\vec j\\parallel+\\hat y$ and $\\vec B\\parallel+\\hat z$ the electrons drift along $-\\hat y$ and the force $-e\\vec v\\times\\vec B$ pushes them to the $+x$ edge, building $E_x=+j_yB_z/(ne)$ (check the direction in your sketch, it was part of the exam's 3 points). Holes drift the other way but are deflected to the same edge: the Hall voltage reverses and $R_H=+1/(pe)>0$."),
       step('mu', "Mobility $\\mu=1/(ne\\rho)=|R_H|/\\rho$ in m$^2$/(V s).", "1/(n*e*rho)", "m^2/(V s)", ["m^2/(V s)", "m/s", "m^2/V", "S/m"], 0.02,
            "$\\mu=e\\tau/m^*=\\sigma/ne$. Semiconductors reach $0.1$–$1$ m$^2$/Vs, metals only $\\sim5\\times10^{-3}$."),
       step('tau', "Relaxation time $\\tau=\\mu m^*/e$ in s.", "mu*ms*me/e", "s", ["s", "fs", "m", "ps"], 0.03,
            "$\\mu m^*/e\\approx1.1\\times10^{-13}$ s. Mind the **effective** mass here, not $m_e$.", bonus=True),
       step('UHcu', "(Bonus) The Hall voltage the same geometry would give in copper ($n=8.47\\times10^{28}$ m$^{-3}$) in nV.", "I*B/(8.47e28*e*d)*1e9", "nV", ["nV", "mV", "uV", "V"], 0.03,
            "$U_H=IB/(ned)=0.37$ nV: Hall measurements on metals are hard, which is why the Hall effect is the semiconductor workhorse.", bonus=True)],
      70)

    c4 = calc('c4', "Residual resistivity ratio: how clean is a crystal?", 'fermi',
      "Quick fight. A very pure copper wire has $\\rho(300\\,{\\rm K})=1.7\\times10^{-8}\\,\\Omega$m and $\\rho(4\\,{\\rm K})=1.7\\times10^{-11}\\,\\Omega$m (RRR $=1000$; script 4.2.5: at low $T$ phonons are frozen out and only defects remain). Use $n=8.47\\times10^{28}$ m$^{-3}$ and $v_F=1.57\\times10^6$ m/s. Estimate the mean free path at 4 K (within a factor of 1.3).",
      V('e', n=8.47e28, rho0=1.7e-11, vF=1.57e6),
      [step('tau0', "Relaxation time at 4 K in s.", "me/(n*e**2*rho0)", "s", ["s", "ns", "fs", "m"], 0.1,
            "$\\tau=m/(ne^2\\rho_0)$: 1000 times larger than at 300 K: $2.5\\times10^{-11}$ s.", tolType='log'),
       step('ell0', "Mean free path $\\ell=v_F\\tau$ at 4 K in micrometres.", "vF*tau0*1e6", "um", ["um", "nm", "mm", "A"], 0.1,
            "About 40 $\\mu$m: the electron travels $10^5$ lattice constants between collisions, a macroscopic fraction of a thin film. Defect density $n_d\\simeq1/(\\ell Q)$ with $Q\\sim\\pi(0.1\\,{\\rm nm})^2$ is $\\sim10^{21}$ m$^{-3}$, one defect per $10^8$ atoms.", tolType='log')],
      20)

    SRC = dict(file="materials/solid-state/old-exams/HS23 (1).pdf", where="Problem 2a (a)-(d) and 2b (e)-(i) (Zheludev, 16 Aug 2024); solution: solutions/Einführung in die Festkörperphysik HS23 (Solution).pdf, Problems 2a/2b")
    boss1 = boss('b1', "Boss: a metal under pressure (exam problem)", SRC, 35,
      "Solve on paper under the timer. The ratios are exact numbers: enter them with at least 3 significant digits.",
      ["We consider the effect of pressure on the electronic properties of a 3D metal. The metal has a simple cubic crystal structure with one atom per unit cell, edge length $a$. Metal A is the material at rest; metal B is the same material under pressure, with the cell edge reduced to $0.9a$. The dispersion of the conduction electrons is the free-electron one, $E=\\hbar^2k^2/2m$. Hint: constants that cancel in a ratio need not be written out. (Marks as printed on the cover sheet: Problem 2a = 3 pt for (a)-(d), Problem 2b = 3 pt for (e)-(i); the solution key splits them 0.5 to 1 pt per part.)",
       "(a) If the base material has Fermi energy $E_{FA}$, what is $E_{FB}$ after applying pressure? Find $E_{FB}/E_{FA}$.",
       "(b) The Fermi surface of A has area $S_A$. Express the Fermi surface area after pressure through $S_A$.",
       "(c) Compare the density of states $\\nu(\\epsilon_F)$ before and after: $\\nu_B(\\epsilon_F)/\\nu_A(\\epsilon_F)$.",
       "(d) Compare the electronic specific heat per volume $c_V=C_V/V$ at 10 K: $c_{V,B}/c_{V,A}$.",
       "(e) Assuming equal Debye temperature in A and B: does the density of phonon states change? Find $\\nu_B(\\omega)/\\nu_A(\\omega)$.",
       "(f) At high temperature $T\\gg\\Theta_D$ electrons scatter mainly from phonons, the scattering rate $\\tau^{-1}$ being proportional to the **density** of phonons. With $\\Theta_D=100$ K unchanged by pressure, compare the resistivities at 300 K: $\\rho_B/\\rho_A$.",
       "In reality pressure shifts all phonon frequencies: $\\Delta\\omega/\\omega=-\\gamma\\,\\Delta V/V$ with Grüneisen parameter $\\gamma=2$.",
       "(g) What is the change of the sound velocity, $v_B/v_A$?  (h) For metal A, $\\Theta_D=100$ K: what is $\\Theta_D$ after pressure?  (i) Including the change of $\\Theta_D$, which metal has the higher resistivity? Does this change the answer to (f)? Explain."],
      [fa('EF', "(a) $E_{FB}/E_{FA}$.", "(1/0.9)**2", dict(), 0.005),
       fa('nu', "(c) $\\nu_B(\\epsilon_F)/\\nu_A(\\epsilon_F)$.", "1/0.9", dict(), 0.005),
       fa('cv', "(d) $c_{V,B}/c_{V,A}$.", "1/0.9", dict(), 0.005),
       fa('nuph', "(e) $\\nu_B(\\omega)/\\nu_A(\\omega)$.", "(1/0.9)**3", dict(), 0.005),
       fa('rho', "(f) $\\rho_B/\\rho_A$ at fixed $\\Theta_D$.", "((1/0.9)**3)*(1/(1/0.9)**3)", dict(), 0.005),
       fa('v', "(g) $v_B/v_A$ with $\\Delta V/V=0.9^3-1$.", "0.9*(1+gam*(1-0.9**3))", dict(gam=2), 0.005),
       fa('Th', "(h) $\\Theta_D$ of B in K.", "ThetaA*(1+gam*(1-0.9**3))", dict(gam=2, ThetaA=100), 0.005),
       fa('rhoi', "(i) $\\rho_A/\\rho_B$ with the Debye-temperature change included.", "1+gam*(1-0.9**3)", dict(gam=2), 0.005)],
      ["(a) $n_iV/a^3=\\frac{2V}{(2\\pi)^3}\\frac{4\\pi}3k_F^3$, so $k_F\\propto1/a$ and $E_F\\propto k_F^2$: $E_{FB}/E_{FA}=(1/0.9)^2\\approx1.23$.",
       "(b) $S=4\\pi k_F^2$: $S_B=(1/0.9)^2S_A\\approx1.23\\,S_A$.",
       "(c) $\\nu(\\epsilon)=\\frac{m^{3/2}}{\\pi^2\\hbar^3}\\sqrt{2\\epsilon}$, so $\\nu(\\epsilon_F)\\propto k_F$: ratio $1/0.9\\approx1.11$.",
       "(d) $c_V=\\frac{\\pi^2}{3}\\nu(\\epsilon_F)k_B^2T$: same ratio $1/0.9$.",
       "(e) Debye: $\\nu(\\omega)=\\frac{9n}{V_0\\omega_D^3}\\omega^2\\Theta(\\omega_D-\\omega)$; with $\\omega_D$ fixed it scales as $1/V_0$: $(1/0.9)^3\\approx1.37$.",
       "(f) $\\rho=\\dfrac{3}{(ev_F)^2\\tau\\nu(\\epsilon_F)}\\propto\\dfrac{1}{k_F^2\\nu\\,\\tau}$ with $\\tau^{-1}\\propto1/V$ and $k_F^2\\nu\\propto n\\propto1/V$: the two effects cancel and $\\rho_B/\\rho_A=1$.",
       "(g) $\\Delta V/V=0.9^3-1=-0.271$, so $\\omega_B=(1+2\\times0.271)\\omega_A=1.54\\omega_A$. The zone boundary moves out ($q_{\\max}\\propto\\pi/a$ grows by $1/0.9$), so $v=\\partial\\omega/\\partial q$ changes by $0.9\\times1.54\\approx1.39$.",
       "(h) $\\Theta_D\\propto\\omega_D\\propto v/V_0^{1/3}$: $\\Theta_{D,B}/\\Theta_{D,A}=1.39/0.9=1.54$, i.e. $\\approx154$ K.",
       "(i) Now $N_p\\propto1/(\\hbar\\omega_DV_0)$ and so $\\rho_A/\\rho_B\\approx1.54$: metal A (at ambient pressure) has the higher resistivity. This changes (f), where they were equal. Stiffer lattice, fewer phonons, better conductor.",
       "Note: constants and conventions are set by the problem; the key writes the Wiedemann–Franz coefficient as $\\pi^2k_B^2/2e^2$ in a related problem (script 4.41 has $\\pi^2/3$)."],
      100)

    return dict(file='drift-corridor', id='ss-drift-corridor', region="Solid State Crystal Caverns", title="The Drift Corridor", course="solid-state",
      topics=["Drude model, mobility, mean free path", "Hall effect", "scattering: phonons (T, T^5), defects, e-e", "Matthiessen's rule, residual resistivity", "Wiedemann–Franz law", "Grüneisen parameter and pressure"],
      sources=[dict(file="materials/solid-state/old-exams/HS23.pdf", where="Problem 2b (d)-(h) (Zheludev, Jan 2024); solution (1), Problem 2b"),
               dict(file="materials/solid-state/old-exams/HS23 (1).pdf", where="Problems 2a/2b (Aug 2024): metal under pressure; solution: HS23 (Solution).pdf"),
               dict(file="materials/solid-state/old-exams/HS20.pdf", where="Task 3 Halleffekt (12 pt), MC (d) resistivity for T->0, MC (q) scattering processes"),
               dict(file="materials/solid-state/scripts/Script-2026_2026-09-01.pdf", where="Ch. 4.1 (pp. 93–95 Drude, Hall), 4.2.5 (pp. 102–106 relaxation), 4.3 (pp. 106–110 thermal conductivity, Wiedemann–Franz)"),
               dict(file="notes/solid-state/03-electrons-and-transport.md", where="transcription, formulas and checks")],
      links=[dict(course="qm", room="tunneling-bridge", why="Why a perfect lattice does not scatter: Bloch waves are exact eigenstates, like the transmission resonances of a periodic array of barriers (transfer matrix, sheet 5)."),
             dict(course="astro", room="stellar-forge", why="Electron conduction and electron-scattering opacity: the same $\\sigma_T/m_p$ that sets the Eddington limit; electron degeneracy also governs conductive transport in white-dwarf cores.")],
      intro="Apply a field and the Fermi sea shifts. How fast do electrons drift, what scatters them, and what do the Hall voltage and the temperature dependence of the resistivity tell you? This corridor is where ratio problems ('compare metals A and B') live.",
      encounters=[c1, c2, c3, c4, boss1])
